    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
        String sheetId = sheet.getId();
        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
                .map(Rate::getRate)
