395	    @Transactional
396	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
397	        sheets.load(sheetId, user);
398	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
399	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
400	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
401	        refuseIfClosed(sheetId, claim.getDate());
