467	     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
468	     *  dated inside a closed period. */
469	    @Transactional
470	    public Claim reject(String sheetId, String user, long id, String reason) {
471	        sheets.load(sheetId, user);
472	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
473	        Claim claim = pendingClaim(sheetId, user, id);
474	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
475	        Rollup.Figures before = rollup.of(sheetId);
476	        claim.setStatus(ClaimStatus.OPEN);
477	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
478	        Claim changed = claims.saveAndFlush(claim);
479	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
480	                + " reason=" + reason.trim());
481	        rollup.recordChanges(sheetId, user, before);
482	        return changed;
483	    }
484	
485	    /** A steward re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an open
486	     *  claim bound by no statement (its live figure at today's rates, grades and floor, with the late charge it
487	     *  would have gained by today on top), and its status log gains a SETTLED line. Refused for a clerk, for a
488	     *  claim that is not SETTLED and for one dated inside a closed period. */
489	    @Transactional
490	    public Claim resettle(String sheetId, String user, long id) {
491	        sheets.load(sheetId, user);
492	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
493	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
494	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
495	        refuseIfClosed(sheetId, claim.getDate());
496	        if (claim.getStatus() != ClaimStatus.SETTLED) {
497	            throw new ResponseStatusException(HttpStatus.CONFLICT,
498	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
499	        }
500	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
501	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
502	        }
503	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
504	        BigDecimal live = liveNow(sheet, claim, person);
505	        BigDecimal due = live == null ? null : live.add(lateChargeAsOpen(claim, live, sheet));
506	        Rollup.Figures before = rollup.of(sheetId);
507	        String old = dueText(claim);
508	        claim.setSettledDue(due);
509	        claim.logStatus(user, sheet.getToday(), due);
510	        Claim changed = claims.saveAndFlush(claim);
511	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, changed, changed.getNumber())
512	                + " old=" + old + " new=" + dueText(changed));
513	        rollup.recordChanges(sheetId, user, before);
514	        return changed;
515	    }
516	
517	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
518	     *  loses any figure a statement bound it to (it is live again until its new person's next statement), and is
519	     *  listed as its new person's newest claim. Refused for a clerk, for a SETTLED or VOID claim, for a move to the
520	     *  person it is already of, for one dated inside a closed period or after the new person retired, and for a
521	     *  correction the new person has no SETTLED claim of that number for. */
522	    @Transactional
523	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
524	        sheets.load(sheetId, user);
525	        sheetStore.findLockedById(sheetId).orElseThrow();
526	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
527	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
528	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
529	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
530	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
531	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
532	        }
533	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
534	            throw new ResponseStatusException(HttpStatus.CONFLICT,
535	                    "A " + claim.getStatus() + " claim cannot be reassigned");
536	        }
537	        if (claim.getPersonId().equals(to.getId())) {
538	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
539	        }
540	        refuseIfClosed(sheetId, claim.getDate());
541	        refuseIfRetired(to, claim.getDate());
542	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
543	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
544	        Rollup.Figures before = rollup.of(sheetId);
545	        claim.unbind();
546	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
547	        Claim moved = claims.saveAndFlush(claim);
548	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
549	                + " from=" + from.getName() + " to=" + to.getName());
550	        rollup.recordChanges(sheetId, user, before);
551	        return moved;
552	    }
553	
554	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
555	     *  dated inside a closed period. */
556	    private Claim pendingClaim(String sheetId, String user, long id) {
557	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
558	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
559	        refuseIfClosed(sheetId, claim.getDate());
560	        if (claim.getStatus() != ClaimStatus.PENDING) {
561	            throw new ResponseStatusException(HttpStatus.CONFLICT,
562	                    "A " + claim.getStatus() + " claim is not waiting for approval");
563	        }
564	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
565	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
566	        }
567	        return claim;
568	    }
569	
570	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
571	     *  gained on top; null when it has no figure. */
572	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
573	        BigDecimal live = liveNow(sheet, claim, person);
574	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained.
575	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
576	        return figure == null ? null : figure.add(lateCharge(claim, figure, sheet));
577	    }
578	
579	    /** A claim's live figure as rates, grades and the floor are now, bound by no statement; null when its grade has
580	     *  no rate in force on its date. */
581	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
582	        String sheetId = sheet.getId();
583	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
584	                .map(Rate::getRate)
585	                .map(rate -> liveFigure(claim, rate, sheet.floorOn(claim.getDate()), sheet.roundingFor(roundingDate(claim,
586	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
587	                .orElse(null);
588	    }
589	
590	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
591	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
592	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
593	    }
594	
595	    private static String dueText(Claim claim) {
596	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
597	    }
598	
599	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
600	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
601	    private String nextNumber(Sheet sheet, LocalDate date) {
602	        if (!sheet.numbersPerPeriod()) {
603	            return String.valueOf(sheet.nextClaimNumber());
604	        }
605	        String prefix = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
606	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
607	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
608	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
609	        String number = sequence.next();
610	        sequences.save(sequence);
611	        return number;
612	    }
613	
614	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
615	     *  clerk limit (a claim with no due is within any limit). */
616	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
617	        BigDecimal limit = sheet.getClerkLimit();
618	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
619	            return false;
620	        }
621	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
622	    }
623	
624	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
625	     *  and a claim that is not a correction but names one. */
626	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
627	        if (amount.signum() >= 0) {
628	            if (corrects != null) {
629	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
630	                        "Only a correction (a negative amount) names a claim it corrects");
631	            }
632	            return;
633	        }
634	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
635	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
636	        if (!settled) {
637	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
638	                    "A correction must name the number of a SETTLED claim of the same person");
639	        }
640	    }
641	
642	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
643	    private void refuseIfClosed(String sheetId, LocalDate date) {
644	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
645	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
646	        }
647	    }
648	
649	    /** Refuse a claim dated after its person's retirement date. */
650	    private static void refuseIfRetired(Person person, LocalDate date) {
651	        if (person.refusesClaimOn(date)) {
652	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
653	                    "That claim is dated after " + person.getName() + " retired");
654	        }
655	    }
656	
657	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
658	    private static String entry(String event, String user, Person person, Claim claim, String number) {
659	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
660	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
661	                + (number == null ? "" : " number=" + number);
662	    }
663	
664	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
665	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
666	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
667	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
668	    }
669	
670	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
671	     *  claim of the same person it corrects. */
672	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
673	        if (claim.getCorrects() == null) {
674	            return claim.getDate();
675	        }
676	        return sheetClaims.stream()
677	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
678	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
679	    }
680	
681	    /** The late charge an OPEN or PENDING claim has gained on its figure by the sheet's today: the late percent in force on its date of
682	     *  the figure for every full 30 days past the day it is due by, rounded as the claim rounds; 0.00 when not overdue,
683	     *  it has no figure, or it is a correction. */
684	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
685	        BigDecimal none = BigDecimal.ZERO.setScale(2);
686	        if (!claim.getStatus().isOpen()) {
687	            return none;
688	        }
689	        return lateChargeAsOpen(claim, figure, sheet);
690	    }
691	
692	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
693	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
694	        BigDecimal none = BigDecimal.ZERO.setScale(2);
695	        if (figure == null || claim.isCorrection()) {
696	            return none;
697	        }
698	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
699	        return periods <= 0 ? none : dueOn(figure, sheet.latePctOn(claim.getDate()).multiply(BigDecimal.valueOf(periods)),
700	                sheet.roundingFor(claim.getDate()));
701	    }
702	
703	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds, raised to the floor
704	     *  (the one in force on its date) unless it is a correction. */
705	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, BigDecimal floor, RoundingMode rounding) {
706	        BigDecimal due = dueOn(claim.getAmount(), rate, rounding);
707	        return claim.isCorrection() ? due : floored(due, floor);
708	    }
709	
710	    /** A live due raised to the sheet's floor when it is below it. */
711	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
712	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
713	    }
714	
715	    private static BigDecimal scaled(BigDecimal amount) {
716	        return amount.setScale(2, RoundingMode.UNNECESSARY);
717	    }
718	
719	    private static String noteOf(String note) {
720	        return note == null ? "" : note.trim();
721	    }
722	}
723	package net.officefloor.hq.app.rollup;
724	
725	import java.math.BigDecimal;
726	import java.math.RoundingMode;
727	import java.time.LocalDate;
728	import java.util.LinkedHashMap;
729	import java.util.List;
730	import java.util.Map;
731	import java.util.Objects;
732	import java.util.stream.Stream;
733	import net.officefloor.hq.app.Audit;
734	import net.officefloor.hq.app.claim.Claim;
735	import net.officefloor.hq.app.claim.ClaimRepository;
736	import net.officefloor.hq.app.claim.ClaimService;
737	import net.officefloor.hq.app.person.Person;
738	import net.officefloor.hq.app.person.PersonRepository;
739	import net.officefloor.hq.app.rate.Rate;
740	import net.officefloor.hq.app.rate.RateRepository;
741	import net.officefloor.hq.app.sheet.Sheet;
742	import net.officefloor.hq.app.sheet.SheetRepository;
743	import org.springframework.stereotype.Service;
744	
745	/**
746	 * The figures of a sheet as the screen shows them: each person's claimed, due-total and overdue-total, and the
747	 * sheet's claimed-total, due-total and overdue-total. A change takes the figures before it and, once made, records
748	 * a ROLLUP line for each person whose figures moved and a TOTALS line when any of the sheet's totals moved.
749	 */
750	@Service
751	public class Rollup {
752	
753	    /** A person's figures: claimed, due-total and overdue-total, each with two decimals; due-total is "n/a" when they
754	     *  have none. */
755	    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {
756	    }
757	
758	    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
759	    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {
760	    }
761	
762	    private static final String NOT_AVAILABLE = "n/a";
763	
764	    private final SheetRepository sheets;
765	    private final PersonRepository people;
766	    private final ClaimRepository claims;
767	    private final RateRepository rates;
768	    private final Audit audit;
769	
770	    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateRepository rates,
771	            Audit audit) {
772	        this.sheets = sheets;
773	        this.people = people;
774	        this.claims = claims;
775	        this.rates = rates;
776	        this.audit = audit;
777	    }
778	
779	    /** The sheet's figures as the store holds them now. */
780	    public Figures of(String sheetId) {
781	        Sheet sheet = sheets.findById(sheetId).orElse(null);
782	        LocalDate today = sheet == null ? null : sheet.getToday();
783	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
784	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
785	        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
786	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
787	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
788	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
789	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
790	            List<Claim> counting = sheetClaims.stream()
791	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c))
792	                    .toList();
793	            BigDecimal claimed = counting.stream().map(Claim::getAmount)
794	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
795	            claimedTotal = claimedTotal.add(claimed);
796	            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
797	            // any of their claims is at, and no claim that has a due, the person has no due-total.
798	            List<BigDecimal> dues = counting.stream()
799	                    .map(c -> dueOf(c, ratesOf(sheetRates, person.gradeOn(c.getDate())), sheet, sheetClaims))
800	                    .filter(Objects::nonNull)
801	                    .toList();
802	            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
803	                            counting.stream().map(c -> person.gradeOn(c.getDate())))
804	                    .anyMatch(grade -> Rate.inForceOn(ratesOf(sheetRates, grade), today).isPresent());
805	            String due = NOT_AVAILABLE;
806	            if (!dues.isEmpty() || anyRate) {
807	                BigDecimal sum = dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
808	                BigDecimal total = sheet == null ? sum : sheet.capped(sum);
809	                dueTotal = dueTotal.add(total);
810	                due = total.toPlainString();
811	            }
812	            // As on screen: the dues of the claims that count which are open and due by a day before the sheet's today.
813	            BigDecimal overdue = counting.stream()
814	                    .filter(c -> today != null && c.getStatus().isOpen() && c.getDueBy().isBefore(today))
815	                    .map(c -> dueOf(c, ratesOf(sheetRates, person.gradeOn(c.getDate())), sheet, sheetClaims))
816	                    .filter(Objects::nonNull)
817	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
818	            overdueTotal = overdueTotal.add(overdue);
819	            byPerson.put(person.getId(),
820	                    new PersonFigures(person.getName(), claimed.toPlainString(), due, overdue.toPlainString()));
821	        }
822	        return new Figures(byPerson, claimedTotal.toPlainString(), dueTotal.toPlainString(),
823	                overdueTotal.toPlainString());
824	    }
825	
826	    /** Each person's due-total for the dates from {@code from} to {@code to} inclusive, by person id, as the screen
827	     *  shows a person's period figure: the dues of their claims that count (a held person's open ones dated within a
828	     *  hold and not stated do not) dated in it, none counting as 0; every person on the sheet has one. */
829	    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
830	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
831	        Sheet sheet = sheets.findById(sheetId).orElse(null);
832	        Map<Long, Person> personOf = new LinkedHashMap<>();
833	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
834	        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> {
835	            personOf.put(p.getId(), p);
836	            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
837	        });
838	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
839	        for (Claim claim : sheetClaims) {
840	            Person person = personOf.get(claim.getPersonId());
841	            if (person == null || !person.counts(claim) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
842	                continue;
843	            }
844	            BigDecimal due = dueOf(claim, ratesOf(sheetRates, person.gradeOn(claim.getDate())), sheet, sheetClaims);
845	            if (due != null) {
846	                totals.merge(person.getId(), due, BigDecimal::add);
847	            }
848	        }
849	        return totals;
850	    }
851	
852	    /**
853	     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
854	     * for each person whose figures changed (one who did not exist before counting as changed), then a
855	     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
856	     */
857	    public void recordChanges(String sheetId, String user, Figures before) {
858	        Figures after = of(sheetId);
859	        after.people().forEach((id, figures) -> {
860	            PersonFigures was = before.people().get(id);
861	            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
862	                    || !was.overdueTotal().equals(figures.overdueTotal())) {
863	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
864	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
865	                        + " overdue-total=" + figures.overdueTotal());
866	            }
867	        });
868	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
869	                || !before.overdueTotal().equals(after.overdueTotal())) {
870	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
871	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
872	        }
873	    }
874	
875	    /** The rates of one grade among a sheet's. */
876	    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
877	        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
878	    }
879	
880	    /** A claim's due: its settled figure, else its stated one (none while PENDING), else its amount at the rate in force on its date of
881	     *  its person's grade in force on that date, rounded as the claim rounds (by the sheet's policy date), raised to the sheet's floor unless it is a correction; an overdue claim's late charge is added on top of the figure. */
882	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, Sheet sheet, List<Claim> sheetClaims) {
883	        if (claim.getSettledDue() != null) {
884	            return claim.getSettledDue();
885	        }
886	        BigDecimal floor = sheet == null ? null : sheet.floorOn(claim.getDate());
887	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
888	                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
889	        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
890	                : Rate.inForceOn(gradeRates, claim.getDate())
891	                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), floor, rounding))
892	                        .orElse(null);
893	        return figure == null || sheet == null ? figure : figure.add(ClaimService.lateCharge(claim, figure, sheet));
894	    }
895	}
